//! How each Pocket Edition block looks: a coarse shape plus, per face, a tile
//! of the texture atlas (or a flat colour for blocks the pack doesn't cover).
//!
//! The textures are Pixel Perfection by XSSheep (CC BY-SA 4.0), see
//! `assets/ATTRIBUTION.md`. Per-face shading is done by the mesher.

/// The texture atlas, generated by `build.rs` from `assets/textures/`.
pub mod atlas {
    include!(concat!(env!("OUT_DIR"), "/atlas.rs"));
}

use atlas::tile as t;

/// Index of a 16x16 tile in the atlas; `t::WHITE` is a solid white tile.
pub type Tile = u16;

/// Coarse geometry used by the mesher.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shape {
    /// Nothing to draw.
    Air,
    /// A full opaque cube; hides the faces of its neighbours.
    Cube,
    /// A full cube drawn translucent (water, glass, ice). Faces between two
    /// blocks of the same kind are skipped.
    Translucent,
    /// An opaque box from the floor up to the given height (slabs, snow, carpet, rails).
    Partial(f32),
    /// Two crossed quads (flowers, grass, saplings, torches).
    Cross,
}

/// Which render pass draws a block; they differ in how texture alpha is used.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Layer {
    /// Alpha ignored.
    Opaque,
    /// Pixels with alpha below one half are discarded (leaves, plants, rails).
    Cutout,
    /// Alpha-blended (water, glass).
    Blend,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Look {
    pub shape: Shape,
    pub layer: Layer,
    /// Linear-ish sRGB colour, 0..1. Only matters for faces on the white tile,
    /// i.e. blocks without a texture; textured blocks use white.
    pub color: [f32; 3],
    /// Extra alpha for translucent blocks, multiplied with the texture's.
    pub alpha: f32,
    /// Atlas tile per face, in the mesher's face order: +x, -x, +y, -y, +z, -z.
    pub tiles: [Tile; 6],
}

const fn rgb(r: u8, g: u8, b: u8) -> [f32; 3] {
    [r as f32 / 255.0, g as f32 / 255.0, b as f32 / 255.0]
}

const WHITE: [f32; 3] = [1.0; 3];
const FLAT: [Tile; 6] = [t::WHITE; 6];

const fn new(shape: Shape, layer: Layer, color: [f32; 3], alpha: f32, tiles: [Tile; 6]) -> Look {
    Look { shape, layer, color, alpha, tiles }
}

// Flat-coloured fallbacks.

const fn cube(c: [f32; 3]) -> Look {
    new(Shape::Cube, Layer::Opaque, c, 1.0, FLAT)
}

const fn partial(h: f32, c: [f32; 3]) -> Look {
    new(Shape::Partial(h), Layer::Opaque, c, 1.0, FLAT)
}

// Textured blocks.

/// A full cube.
const fn solid(tiles: [Tile; 6]) -> Look {
    new(Shape::Cube, Layer::Opaque, WHITE, 1.0, tiles)
}

/// A full cube with see-through pixels (leaves, spawner).
const fn solid_cutout(tiles: [Tile; 6]) -> Look {
    new(Shape::Cube, Layer::Cutout, WHITE, 1.0, tiles)
}

/// A box up to height `h`; side faces show the bottom `h` of their tile.
const fn slab(h: f32, tiles: [Tile; 6]) -> Look {
    new(Shape::Partial(h), Layer::Opaque, WHITE, 1.0, tiles)
}

/// A box with see-through pixels (rails, ladders, lily pads).
const fn slab_cutout(h: f32, tiles: [Tile; 6]) -> Look {
    new(Shape::Partial(h), Layer::Cutout, WHITE, 1.0, tiles)
}

const fn plant(tile: Tile) -> Look {
    new(Shape::Cross, Layer::Cutout, WHITE, 1.0, [tile; 6])
}

/// A translucent cube whose transparency comes from the texture.
const fn glassy(tile: Tile) -> Look {
    new(Shape::Translucent, Layer::Blend, WHITE, 1.0, [tile; 6])
}

const AIR: Look = new(Shape::Air, Layer::Opaque, [0.0; 3], 0.0, FLAT);

// Per-face tile layouts, in face order +x, -x, +y, -y, +z, -z.

const fn all(tile: Tile) -> [Tile; 6] {
    [tile; 6]
}

const fn column(top: Tile, side: Tile, bottom: Tile) -> [Tile; 6] {
    [side, side, top, bottom, side, side]
}

/// `tiles` with the face pointing in Java-style direction `dir` (0 down, 1 up,
/// 2 north/-z, 3 south/+z, 4 west/-x, 5 east/+x) replaced by `front`.
fn facing(mut tiles: [Tile; 6], dir: u8, front: Tile) -> [Tile; 6] {
    const FACE: [usize; 6] = [3, 2, 5, 4, 1, 0];
    tiles[FACE[dir as usize % 6]] = front;
    tiles
}

/// A log: `end` caps on the axis given by the data's orientation bits.
fn log(end: Tile, bark: Tile, data: u8) -> [Tile; 6] {
    match data & 12 {
        4 => [end, end, bark, bark, bark, bark],
        8 => [bark, bark, bark, bark, end, end],
        12 => all(bark),
        _ => column(end, bark, end),
    }
}

/// The 16 wool / terracotta / stained glass colours, by data value.
const WOOL: [Tile; 16] = [
    t::WHITE_WOOL, t::ORANGE_WOOL, t::MAGENTA_WOOL, t::LIGHT_BLUE_WOOL, t::YELLOW_WOOL, t::LIME_WOOL,
    t::PINK_WOOL, t::GRAY_WOOL, t::LIGHT_GRAY_WOOL, t::CYAN_WOOL, t::PURPLE_WOOL, t::BLUE_WOOL,
    t::BROWN_WOOL, t::GREEN_WOOL, t::RED_WOOL, t::BLACK_WOOL,
];
const TERRACOTTA: [Tile; 16] = [
    t::WHITE_TERRACOTTA, t::ORANGE_TERRACOTTA, t::MAGENTA_TERRACOTTA, t::LIGHT_BLUE_TERRACOTTA,
    t::YELLOW_TERRACOTTA, t::LIME_TERRACOTTA, t::PINK_TERRACOTTA, t::GRAY_TERRACOTTA,
    t::LIGHT_GRAY_TERRACOTTA, t::CYAN_TERRACOTTA, t::PURPLE_TERRACOTTA, t::BLUE_TERRACOTTA,
    t::BROWN_TERRACOTTA, t::GREEN_TERRACOTTA, t::RED_TERRACOTTA, t::BLACK_TERRACOTTA,
];
const STAINED_GLASS: [Tile; 16] = [
    t::WHITE_STAINED_GLASS, t::ORANGE_STAINED_GLASS, t::MAGENTA_STAINED_GLASS,
    t::LIGHT_BLUE_STAINED_GLASS, t::YELLOW_STAINED_GLASS, t::LIME_STAINED_GLASS,
    t::PINK_STAINED_GLASS, t::GRAY_STAINED_GLASS, t::LIGHT_GRAY_STAINED_GLASS,
    t::CYAN_STAINED_GLASS, t::PURPLE_STAINED_GLASS, t::BLUE_STAINED_GLASS, t::BROWN_STAINED_GLASS,
    t::GREEN_STAINED_GLASS, t::RED_STAINED_GLASS, t::BLACK_STAINED_GLASS,
];

/// Planks by wood type (oak, spruce, birch, jungle, acacia, dark oak).
const PLANKS: [Tile; 6] =
    [t::OAK_PLANKS, t::SPRUCE_PLANKS, t::BIRCH_PLANKS, t::JUNGLE_PLANKS, t::ACACIA_PLANKS, t::DARK_OAK_PLANKS];

const SAPLINGS: [Tile; 6] = [
    t::OAK_SAPLING, t::SPRUCE_SAPLING, t::BIRCH_SAPLING, t::JUNGLE_SAPLING, t::ACACIA_SAPLING,
    t::DARK_OAK_SAPLING,
];

const WHEAT: [Tile; 8] = [
    t::WHEAT_STAGE0, t::WHEAT_STAGE1, t::WHEAT_STAGE2, t::WHEAT_STAGE3, t::WHEAT_STAGE4,
    t::WHEAT_STAGE5, t::WHEAT_STAGE6, t::WHEAT_STAGE7,
];

/// Crop growth, 0..=7, to a four-stage texture index (carrots, potatoes).
fn crop_stage(data: u8) -> usize {
    match data & 7 {
        0 | 1 => 0,
        2 | 3 => 1,
        4..=6 => 2,
        _ => 3,
    }
}

/// Slab and double slab materials, by data value.
fn slab_tiles(data: u8) -> [Tile; 6] {
    match data & 7 {
        0 => column(t::STONE_SLAB_TOP, t::STONE_SLAB_SIDE, t::STONE_SLAB_TOP),
        1 => column(t::SANDSTONE_TOP, t::SANDSTONE, t::SANDSTONE_BOTTOM),
        2 => all(t::OAK_PLANKS),
        3 => all(t::COBBLESTONE),
        4 => all(t::BRICKS),
        5 => all(t::STONE_BRICKS),
        6 => column(t::QUARTZ_BLOCK_TOP, t::QUARTZ_BLOCK_SIDE, t::QUARTZ_BLOCK_BOTTOM),
        _ => all(t::NETHER_BRICKS),
    }
}

/// Appearance of a Pocket Edition block.
pub fn look(id: u8, data: u8) -> Look {
    let d = data as usize;
    match id {
        0 => AIR,
        1 => solid(all(match data {
            1 => t::GRANITE,
            2 => t::POLISHED_GRANITE,
            3 => t::DIORITE,
            4 => t::POLISHED_DIORITE,
            5 => t::ANDESITE,
            6 => t::POLISHED_ANDESITE,
            _ => t::STONE,
        })),
        2 => solid(column(t::GRASS_BLOCK_TOP, t::GRASS_BLOCK_SIDE, t::DIRT)),
        3 => solid(all(if data == 1 { t::COARSE_DIRT } else { t::DIRT })),
        4 => solid(all(t::COBBLESTONE)),
        5 | 125 | 157 => solid(all(PLANKS[d % 6])),
        6 => plant(SAPLINGS[(d & 7) % 6]),
        31 => plant(match data {
            1 => t::GRASS,
            2 => t::FERN,
            _ => t::DEAD_BUSH,
        }),
        32 => plant(t::DEAD_BUSH),
        37 => plant(t::DANDELION),
        38 => plant(match data {
            0 => t::POPPY,
            1 => t::BLUE_ORCHID,
            2 => t::ALLIUM,
            3 => t::AZURE_BLUET,
            4 => t::RED_TULIP,
            5 => t::ORANGE_TULIP,
            6 => t::WHITE_TULIP,
            7 => t::PINK_TULIP,
            _ => t::OXEYE_DAISY,
        }),
        39 => plant(t::BROWN_MUSHROOM),
        40 => plant(t::RED_MUSHROOM),
        59 => plant(WHEAT[d & 7]),
        83 => plant(t::REEDS),
        106 => plant(t::VINE),
        141 => plant([t::CARROTS_STAGE0, t::CARROTS_STAGE1, t::CARROTS_STAGE2, t::CARROTS_STAGE3][crop_stage(data)]),
        142 => plant([t::POTATOES_STAGE0, t::POTATOES_STAGE1, t::POTATOES_STAGE2, t::POTATOES_STAGE3][crop_stage(data)]),
        244 => plant([t::BEETROOTS_STAGE0, t::BEETROOTS_STAGE1, t::BEETROOTS_STAGE2, t::BEETROOTS_STAGE3][(d & 7) / 2]),
        // Double plants: the top half is data bit 8.
        175 => plant(match (data & 7, data & 8 != 0) {
            (0, false) => t::SUNFLOWER_BOTTOM,
            (0, true) => t::SUNFLOWER_FRONT,
            (1, false) => t::LILAC_BOTTOM,
            (1, true) => t::LILAC_TOP,
            (3, false) => t::LARGE_FERN_BOTTOM,
            (3, true) => t::LARGE_FERN_TOP,
            (4, false) => t::ROSE_BUSH_BOTTOM,
            (4, true) => t::ROSE_BUSH_TOP,
            (5, false) => t::PEONY_BOTTOM,
            (5, true) => t::PEONY_TOP,
            (_, false) => t::TALL_GRASS_BOTTOM,
            (_, true) => t::TALL_GRASS_TOP,
        }),
        7 => solid(all(t::BEDROCK)),
        8 | 9 => glassy(t::WATER_STILL),
        10 | 11 => solid(all(t::LAVA_STILL)),
        12 => solid(all(if data == 1 { t::RED_SAND } else { t::SAND })),
        13 => solid(all(t::GRAVEL)),
        14 => solid(all(t::GOLD_ORE)),
        15 => solid(all(t::IRON_ORE)),
        16 => solid(all(t::COAL_ORE)),
        17 => {
            let (end, bark) = match data & 3 {
                1 => (t::SPRUCE_LOG_TOP, t::SPRUCE_LOG),
                2 => (t::BIRCH_LOG_TOP, t::BIRCH_LOG),
                3 => (t::JUNGLE_LOG_TOP, t::JUNGLE_LOG),
                _ => (t::OAK_LOG_TOP, t::OAK_LOG),
            };
            solid(log(end, bark, data))
        }
        162 => {
            let (end, bark) = if data & 3 == 1 {
                (t::DARK_OAK_LOG_TOP, t::DARK_OAK_LOG)
            } else {
                (t::ACACIA_LOG_TOP, t::ACACIA_LOG)
            };
            solid(log(end, bark, data))
        }
        18 => solid_cutout(all(match data & 3 {
            1 => t::SPRUCE_LEAVES,
            2 => t::BIRCH_LEAVES,
            3 => t::JUNGLE_LEAVES,
            _ => t::OAK_LEAVES,
        })),
        161 => solid_cutout(all(if data & 3 == 1 { t::DARK_OAK_LEAVES } else { t::ACACIA_LEAVES })),
        19 => solid(all(t::SPONGE)),
        20 | 102 => glassy(t::GLASS),
        21 => solid(all(t::LAPIS_ORE)),
        22 => solid(all(t::LAPIS_BLOCK)),
        23 => solid(facing(column(t::FURNACE_TOP, t::FURNACE_SIDE, t::FURNACE_TOP), data & 7, t::DISPENSER_FRONT)),
        29 | 33 => {
            let front = if id == 29 { t::PISTON_TOP } else { t::PISTON_TOP_STICKY };
            let sides = facing(all(t::PISTON_SIDE), data & 7, front);
            // The back is the face opposite the front.
            solid(facing(sides, (data & 7) ^ 1, t::PISTON_BOTTOM))
        }
        34 => partial(1.0, rgb(150, 125, 90)), // piston head
        55 => partial(0.0625, rgb(170, 20, 10)), // redstone wire
        93 | 94 => partial(0.125, rgb(160, 150, 150)), // repeater
        24 => solid(match data {
            1 => column(t::CHISELED_SANDSTONE, t::CHISELED_SANDSTONE, t::CHISELED_SANDSTONE),
            2 => all(t::CUT_SANDSTONE),
            _ => column(t::SANDSTONE_TOP, t::SANDSTONE, t::SANDSTONE_BOTTOM),
        }),
        128 => solid(column(t::SANDSTONE_TOP, t::SANDSTONE, t::SANDSTONE_BOTTOM)),
        26 => partial(0.5625, rgb(160, 30, 30)),
        27 => slab_cutout(0.0625, all(if data & 8 != 0 { t::POWERED_RAIL_ON } else { t::POWERED_RAIL })),
        28 => slab_cutout(0.0625, all(if data & 8 != 0 { t::DETECTOR_RAIL_ON } else { t::DETECTOR_RAIL })),
        66 => slab_cutout(0.0625, all(if (6..=9).contains(&data) { t::RAIL_CORNER } else { t::RAIL })),
        126 => slab_cutout(0.0625, all(if data & 8 != 0 { t::ACTIVATOR_RAIL_ON } else { t::ACTIVATOR_RAIL })),
        35 => solid(all(WOOL[d])),
        41 => solid(all(t::GOLD_BLOCK)),
        42 => solid(all(t::IRON_BLOCK)),
        43 => solid(slab_tiles(data)),
        181 => solid(column(t::RED_SANDSTONE_TOP, t::RED_SANDSTONE, t::RED_SANDSTONE_BOTTOM)),
        44 => slab(0.5, slab_tiles(data)),
        182 => slab(0.5, column(t::RED_SANDSTONE_TOP, t::RED_SANDSTONE, t::RED_SANDSTONE_BOTTOM)),
        158 => slab(0.5, all(PLANKS[(d & 7) % 6])),
        45 => solid(all(t::BRICKS)),
        46 => solid(column(t::TNT_TOP, t::TNT_SIDE, t::TNT_BOTTOM)),
        47 => solid(column(t::OAK_PLANKS, t::BOOKSHELF, t::OAK_PLANKS)),
        48 => solid(all(t::MOSSY_COBBLESTONE)),
        49 => solid(all(t::OBSIDIAN)),
        50 => plant(t::TORCH),
        51 => plant(t::FIRE_0),
        52 => solid_cutout(all(t::SPAWNER)),
        53 | 134 | 135 | 136 | 163 | 164 => slab(
            0.5,
            all(match id {
                134 => t::SPRUCE_PLANKS,
                135 => t::BIRCH_PLANKS,
                136 => t::JUNGLE_PLANKS,
                163 => t::ACACIA_PLANKS,
                164 => t::DARK_OAK_PLANKS,
                _ => t::OAK_PLANKS,
            }),
        ),
        54 | 146 => cube(rgb(160, 115, 45)),
        56 => solid(all(t::DIAMOND_ORE)),
        57 => solid(all(t::DIAMOND_BLOCK)),
        58 => solid([
            t::CRAFTING_TABLE_FRONT,
            t::CRAFTING_TABLE_FRONT,
            t::CRAFTING_TABLE_TOP,
            t::OAK_PLANKS,
            t::CRAFTING_TABLE_SIDE,
            t::CRAFTING_TABLE_SIDE,
        ]),
        60 => solid(column(if data > 0 { t::FARMLAND_MOIST } else { t::FARMLAND }, t::DIRT, t::DIRT)),
        61 | 62 => solid(facing(
            column(t::FURNACE_TOP, t::FURNACE_SIDE, t::FURNACE_TOP),
            data & 7,
            if id == 62 { t::FURNACE_FRONT_ON } else { t::FURNACE_FRONT },
        )),
        63 | 68 => slab(0.5, all(t::OAK_PLANKS)),
        64 => solid(all(t::OAK_PLANKS)),
        71 => solid(all(t::IRON_BLOCK)),
        193..=197 => solid(all(t::OAK_PLANKS)),
        65 => slab_cutout(0.125, all(t::LADDER)),
        67 => slab(0.5, all(t::COBBLESTONE)),
        70 => slab(0.0625, all(t::STONE)),
        72 => slab(0.0625, all(t::OAK_PLANKS)),
        147 => slab(0.0625, all(t::GOLD_BLOCK)),
        148 => slab(0.0625, all(t::IRON_BLOCK)),
        69 | 77 | 143 => partial(0.0625, rgb(130, 130, 130)),
        73 | 74 => solid(all(t::REDSTONE_ORE)),
        75 => plant(t::REDSTONE_TORCH_OFF),
        76 => plant(t::REDSTONE_TORCH),
        78 => slab(0.125 * (d as f32 % 8.0 + 1.0), all(t::SNOW)),
        79 => glassy(t::ICE),
        80 => solid(all(t::SNOW)),
        81 => solid(column(t::CACTUS_TOP, t::CACTUS_SIDE, t::CACTUS_BOTTOM)),
        82 => solid(all(t::CLAY)),
        84 => solid(column(t::JUKEBOX_TOP, t::JUKEBOX_SIDE, t::JUKEBOX_SIDE)),
        85 | 107 | 183..=192 => slab(
            1.0,
            all(if id == 85 { PLANKS[d % 6] } else { t::OAK_PLANKS }),
        ),
        86 | 91 => {
            let front = if id == 86 { t::CARVED_PUMPKIN } else { t::JACK_O_LANTERN };
            // Data 0..3 faces south, west, north, east.
            let dir = [3, 4, 2, 5][d & 3];
            solid(facing(column(t::PUMPKIN_TOP, t::PUMPKIN_SIDE, t::PUMPKIN_TOP), dir, front))
        }
        87 => solid(all(t::NETHERRACK)),
        88 => solid(all(t::SOUL_SAND)),
        89 => solid(all(t::GLOWSTONE)),
        92 => slab(0.5, column(t::CAKE_TOP, t::CAKE_SIDE, t::CAKE_BOTTOM)),
        96 => slab_cutout(0.1875, all(t::TRAPDOOR)),
        167 => slab(0.1875, all(t::IRON_TRAPDOOR)),
        97 => solid(all(t::STONE)),
        98 => solid(all(match data {
            1 => t::MOSSY_STONE_BRICKS,
            2 => t::CRACKED_STONE_BRICKS,
            3 => t::CHISELED_STONE_BRICKS,
            _ => t::STONE_BRICKS,
        })),
        99 | 100 => solid(all(match data {
            10 | 15 => t::MUSHROOM_STEM,
            0 => t::MUSHROOM_BLOCK_INSIDE,
            _ if id == 99 => t::BROWN_MUSHROOM_BLOCK,
            _ => t::RED_MUSHROOM_BLOCK,
        })),
        101 => slab_cutout(1.0, all(t::IRON_BARS)),
        103 => solid(column(t::MELON_TOP, t::MELON_SIDE, t::MELON_TOP)),
        104 => plant(t::PUMPKIN_STEM),
        105 => plant(t::MELON_STEM),
        108 => slab(0.5, all(t::BRICKS)),
        109 => slab(0.5, all(t::STONE_BRICKS)),
        110 => solid(column(t::MYCELIUM_TOP, t::MYCELIUM_SIDE, t::DIRT)),
        111 => slab_cutout(0.0625, all(t::LILY_PAD)),
        112..=114 => slab(if id == 114 { 0.5 } else { 1.0 }, all(t::NETHER_BRICKS)),
        115 => plant([t::NETHER_WART_STAGE0, t::NETHER_WART_STAGE1, t::NETHER_WART_STAGE1, t::NETHER_WART_STAGE2][d & 3]),
        116 => slab(0.75, column(t::ENCHANTING_TABLE_TOP, t::ENCHANTING_TABLE_SIDE, t::ENCHANTING_TABLE_BOTTOM)),
        117 => plant(t::BREWING_STAND),
        118 => slab_cutout(1.0, column(t::CAULDRON_TOP, t::CAULDRON_SIDE, t::CAULDRON_BOTTOM)),
        120 => slab(0.8125, column(t::END_PORTAL_FRAME_TOP, t::END_PORTAL_FRAME_SIDE, t::END_STONE)),
        121 => solid(all(t::END_STONE)),
        123 => solid(all(t::REDSTONE_LAMP)),
        124 => solid(all(t::REDSTONE_LAMP_ON)),
        127 => plant([t::COCOA_STAGE0, t::COCOA_STAGE1, t::COCOA_STAGE2][(d >> 2).min(2)]),
        129 => solid(all(t::EMERALD_ORE)),
        133 => solid(all(t::EMERALD_BLOCK)),
        139 => slab(1.0, all(if data == 1 { t::MOSSY_COBBLESTONE } else { t::COBBLESTONE })),
        140 => partial(0.375, rgb(120, 60, 40)),
        145 => partial(1.0, rgb(70, 70, 70)),
        152 => solid(all(t::REDSTONE_BLOCK)),
        153 => solid(all(t::NETHER_QUARTZ_ORE)),
        155 | 156 => {
            let tiles = match data {
                1 => column(t::CHISELED_QUARTZ_BLOCK_TOP, t::CHISELED_QUARTZ_BLOCK, t::CHISELED_QUARTZ_BLOCK_TOP),
                2 => column(t::QUARTZ_PILLAR_TOP, t::QUARTZ_PILLAR, t::QUARTZ_PILLAR_TOP),
                _ => column(t::QUARTZ_BLOCK_TOP, t::QUARTZ_BLOCK_SIDE, t::QUARTZ_BLOCK_BOTTOM),
            };
            if id == 155 { solid(tiles) } else { slab(0.5, tiles) }
        }
        159 => solid(all(TERRACOTTA[d])),
        160 => glassy(STAINED_GLASS[d]),
        165 => glassy(t::SLIME_BLOCK),
        168 => solid(all(match data {
            1 => t::PRISMARINE_BRICKS,
            2 => t::DARK_PRISMARINE,
            _ => t::PRISMARINE,
        })),
        169 => solid(all(t::SEA_LANTERN)),
        170 => solid(column(t::HAY_BLOCK_TOP, t::HAY_BLOCK_SIDE, t::HAY_BLOCK_TOP)),
        171 => slab(0.0625, all(WOOL[d])),
        172 => solid(all(t::TERRACOTTA)),
        173 => solid(all(t::COAL_BLOCK)),
        174 => solid(all(t::PACKED_ICE)),
        179 | 180 => solid(column(t::RED_SANDSTONE_TOP, t::RED_SANDSTONE, t::RED_SANDSTONE_BOTTOM)),
        198 => slab(0.9375, column(t::GRASS_PATH_TOP, t::GRASS_PATH_SIDE, t::DIRT)),
        199 => AIR, // item frame: drawn as an entity in later versions
        201 | 203 | 204 | 205 => solid(all(t::PURPUR_BLOCK)),
        202 => solid(column(t::PURPUR_PILLAR_TOP, t::PURPUR_PILLAR, t::PURPUR_PILLAR_TOP)),
        241 => glassy(STAINED_GLASS[d]),
        243 => solid(column(t::PODZOL_TOP, t::PODZOL_SIDE, t::DIRT)),
        245 => cube(rgb(115, 115, 115)), // stonecutter: not in Pixel Perfection 1.11
        246 => cube(rgb(80, 20, 20)),
        247 => cube(rgb(210, 210, 210)),
        // Unknown blocks are still drawn, in a loud colour, so gaps are visible.
        _ => cube(rgb(255, 0, 255)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_block_in_the_sample_world_has_a_real_look() {
        let w = mcpe_world::World::open_dir(concat!(env!("CARGO_MANIFEST_DIR"), "/../../worlds/My World")).unwrap();
        let mut unknown = std::collections::BTreeSet::new();
        for c in w.columns.values() {
            for (&id, &data) in c.ids.iter().zip(&c.data) {
                if look(id, data).color == rgb(255, 0, 255) {
                    unknown.insert(id);
                }
            }
        }
        assert!(unknown.is_empty(), "blocks without a look: {unknown:?}");
    }
}
